import { describe, it, expect, beforeAll } from 'vitest';
import { parse } from 'node-html-parser';
import { readFileSync } from 'node:fs';
import path from 'node:path';

import { buildLandingPage } from '../src/build';
import { siteConfig } from '../site.config';

const DIST = path.join(__dirname, '..', 'dist', 'index.html');
let root;

beforeAll(() => {
  const html = readFileSync(DIST, 'utf8');
  root = parse(html);
});

describe('semantic structure & accessibility', () => {
  it('exactly one h1', () => {
    const h1s = root.querySelectorAll('h1');
    expect(h1s.length).toBe(1);
    expect(h1s[0].text.trim()).toBe(siteConfig.heroHeading);
  });

  it('heading levels never skip', () => {
    // Collect all headings in document order.
    const headings = [];
    for (const el of root.querySelectorAll('*')) {
      if (/^h[1-6]$/.test(el.rawTagName)) {
        headings.push({ tag: el.rawTagName, level: Number(el.rawTagName[1]) });
      }
    }
    expect(headings.length).toBeGreaterThan(0);
    // First heading must be h1 (no skipping down to a deeper level first).
    expect(headings[0].level).toBe(1);
    for (let i = 1; i < headings.length; i++) {
      const prev = headings[i - 1].level;
      const curr = headings[i].level;
      // A heading may only be at most one level deeper than the previous one.
      expect(curr - prev, `skipped level between ${headings[i - 1].tag} and ${headings[i].tag}`).toBeLessThanOrEqual(1);
    }
  });

  it('every img has non-empty alt', () => {
    const imgs = root.querySelectorAll('img');
    expect(imgs.length).toBeGreaterThan(0);
    for (const img of imgs) {
      const alt = img.getAttribute('alt');
      expect(alt, `img ${img.getAttribute('src')} missing alt`).toBeDefined();
      expect(alt.trim().length, `img ${img.getAttribute('src')} has empty alt`).toBeGreaterThan(0);
    }
  });

  it('feature icons use configured alt text', () => {
    const imgs = root.querySelectorAll('.feature-icon img');
    expect(imgs.length).toBe(siteConfig.features.length);
    imgs.forEach((img, i) => {
      expect(img.getAttribute('alt')).toBe(siteConfig.features[i].iconAlt);
      expect(img.getAttribute('src')).toBe(siteConfig.features[i].iconSrc);
    });
  });
});

describe('landmarks & semantics', () => {
  it('has header, nav with aria-label, main, and footer (contentinfo landmark)', () => {
    expect(root.querySelectorAll('header').length).toBeGreaterThanOrEqual(1);
    expect(root.querySelectorAll('main').length).toBe(1);
    expect(root.querySelectorAll('footer').length).toBe(1);

    const nav = root.querySelector('header nav');
    expect(nav).toBeTruthy();
    expect(nav.getAttribute('aria-label')).toBeTruthy();

    const main = root.querySelector('main');
    expect(main.querySelectorAll('section.feature').length).toBe(3);
    main.querySelectorAll('section.feature').forEach((section) => {
      expect(section.querySelector('h2')).toBeTruthy();
    });
  });
});

describe('nav links', () => {
  it('contains all configured links with correct hrefs', () => {
    const navAnchors = root.querySelectorAll('header nav a');
    expect(navAnchors.length).toBe(siteConfig.navLinks.length);

    const actual = navAnchors.map((a) => ({
      label: a.text.trim(),
      href: a.getAttribute('href'),
    }));

    for (const expected of siteConfig.navLinks) {
      const match = actual.find((a) => a.label === expected.label);
      expect(match, `nav link "${expected.label}" missing`).toBeDefined();
      expect(match.href, `href mismatch for "${expected.label}"`).toBe(expected.href);
    }
  });
});

describe('security hygiene', () => {
  it('no inline event-handler attributes anywhere', () => {
    const all = root.querySelectorAll('*');
    expect(all.length).toBeGreaterThan(0);
    const offenders = [];
    for (const el of all) {
      for (const attr of Object.keys(el.attributes)) {
        if (/^on[a-z]+$/i.test(attr)) offenders.push(`${el.rawTagName}[${attr}]`);
      }
    }
    expect(offenders, `found inline handlers: ${offenders.join(', ')}`).toEqual([]);
  });
});

